1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="My Page">
7	  <meta name="robots" content="index, follow">
8	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
9	  <meta name="theme-color" content="#111214" media="(prefers-color-scheme: dark)">
10	  <meta property="og:title" content="My Page">
11	  <meta property="og:description" content="My Page">
12	  <meta property="og:type" content="website">
13	  <meta property="og:url" content="https://example.com/">
14	  <meta name="twitter:card" content="summary">
15	  <meta name="twitter:title" content="My Page">
16	  <meta name="twitter:description" content="My Page">
17	  <link rel="canonical" href="https://example.com/">
18	  <link rel="icon" href="data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2016%2016'%3E%3Ccircle%20cx='8'%20cy='8'%20r='7'%20fill='%232563eb'/%3E%3C/svg%3E">
19	  <title>My Page</title>
20	  <style>
21	    :root {
22	      color-scheme: light dark;
23	      --bg: #ffffff;
24	      --fg: #1a1a1a;
25	      --muted: #555;
26	      --accent: #2563eb;
27	      --border: #e5e7eb;
28	    }
29	
30	    @media (prefers-color-scheme: dark) {
31	      :root {
32	        --bg: #111214;
33	        --fg: #e8e8e8;
34	        --muted: #aaa;
35	        --accent: #60a5fa;
36	        --border: #2a2b2e;
37	      }
38	    }
39	
40	    * {
41	      box-sizing: border-box;
42	    }
43	
44	    html {
45	      scroll-behavior: smooth;
46	    }
47	
48	    @media (prefers-reduced-motion: reduce) {
49	      html {
50	        scroll-behavior: auto;
51	      }
52	    }
53	
54	    ::selection {
55	      background: var(--accent);
56	      color: var(--bg);
57	    }
58	
59	    body {
60	      font-family: system-ui, -apple-system, sans-serif;
61	      max-width: 40rem;
62	      margin: 3rem auto;
63	      padding: 0 1rem;
64	      line-height: 1.6;
65	      color: var(--fg);
66	      background: var(--bg);
67	    }
68	
69	    @media (max-width: 30rem) {
70	      body {
71	        margin: 1.5rem auto;
72	      }
73	    }
74	
75	    h1 {
76	      font-size: clamp(1.75rem, 5vw, 2.5rem);
77	      margin-bottom: 0.5rem;
78	    }
79	
80	    p {
81	      color: var(--muted);
82	      max-width: 34rem;
83	    }
84	
85	    a {
86	      color: var(--accent);
87	      transition: opacity 0.15s ease;
88	    }
89	
90	    a:hover {
91	      opacity: 0.8;
92	    }
93	
94	    a:focus-visible,
95	    button:focus-visible {
96	      outline: 2px solid var(--accent);
97	      outline-offset: 2px;
98	    }
99	
100	    .skip-link {
101	      position: absolute;
102	      left: -9999px;
103	      top: 0;
104	      background: var(--accent);
105	      color: var(--bg);
106	      padding: 0.5rem 1rem;
107	      border-radius: 0.25rem;
108	      z-index: 10;
109	    }
110	
111	    .skip-link:focus {
112	      left: 1rem;
113	      top: 1rem;
114	    }
115	
116	    main:focus {
117	      outline: none;
118	    }
119	
120	    nav ul {
121	      display: flex;
122	      flex-wrap: wrap;
123	      gap: 1rem;
124	      list-style: none;
125	      padding: 0;
126	      margin: 0 0 2rem;
127	    }
128	
129	    nav a {
130	      text-decoration: none;
131	      font-weight: 500;
132	      opacity: 1;
133	    }
134	
135	    nav a:hover {
136	      text-decoration: underline;
137	    }
138	
139	    nav a[aria-current="page"] {
140	      text-decoration: underline;
141	      color: var(--fg);
142	      font-weight: 700;
143	    }
144	
145	    h2 {
146	      margin-top: 2rem;
147	      margin-bottom: 0.5rem;
148	    }
149	
150	    section + section {
151	      margin-top: 1.5rem;
152	    }
153	
154	    footer {
155	      margin-top: 3rem;
156	      padding-top: 1.5rem;
157	      border-top: 1px solid var(--border);
158	      font-size: 0.875rem;
159	      color: var(--muted);
160	    }
161	  </style>
162	</head>
163	<body>
164	  <a class="skip-link" href="#main">Skip to content</a>
165	  <nav aria-label="Primary">
166	    <ul>
167	      <li><a href="#home" data-nav-link aria-current="page">Home</a></li>
168	      <li><a href="#about" data-nav-link>About</a></li>
169	      <li><a href="#contact" data-nav-link>Contact</a></li>
170	    </ul>
171	  </nav>
172	  <main id="main" tabindex="-1">
173	    <section id="home" aria-labelledby="home-heading">
174	      <h1 id="home-heading">My Page</h1>
175	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
176	    </section>
177	
178	    <section id="about" aria-labelledby="about-heading">
179	      <h2 id="about-heading">About</h2>
180	      <p>Add a short description of what this page or project is about here.</p>
181	    </section>
182	
183	    <section id="contact" aria-labelledby="contact-heading">
184	      <h2 id="contact-heading">Contact</h2>
185	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
186	    </section>
187	  </main>
188	  <footer>
189	    <p>&copy; <span id="year">2026</span> My Page. All rights reserved.</p>
190	  </footer>
191	  <script>
192	    document.getElementById('year').textContent = String(new Date().getFullYear());
193	
194	    const navLinks = document.querySelectorAll('[data-nav-link]');
195	    const sections = [...navLinks].map(link => document.querySelector(link.getAttribute('href')));
196	
197	    const setActive = (id) => {
198	      navLinks.forEach(link => {
199	        if (link.getAttribute('href') === `#${id}`) {
200	          link.setAttribute('aria-current', 'page');
201	        } else {
202	          link.removeAttribute('aria-current');
203	        }
204	      });
205	    };
206	
207	    setActive(sections[0]?.id);
208	
209	    if ('IntersectionObserver' in window) {
210	      const observer = new IntersectionObserver((entries) => {
211	        const visible = entries
212	          .filter(entry => entry.isIntersecting)
213	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
214	        if (visible) setActive(visible.target.id);
215	      }, { rootMargin: '-40% 0px -50% 0px' });
216	      sections.forEach(section => section && observer.observe(section));
217	    }
218	  </script>
219	</body>
220	</html>
